<?php\n/**\n * Script para encontrar e baixar imagens do site CCCRJ\n */\n\nclass ImageFinder {\n    private $baseUrl = \"http://www.cccrj.com.br/\";\n    private $outputDir = \"cccrj_content/images\";\n    private $visitedPages = [];\n    private $downloadedImages = [];\n    private $delay = 1; // segundos entre requisições\n\n    public function __construct() {\n        // Criar diretório de saída para imagens\n        if (!file_exists($this->outputDir)) {\n            mkdir($this->outputDir, 0755, true);\n        }\n    }\n\n    private function getPageContent($url) {\n        $context = stream_context_create([\n            'http' => [\n                'method' => 'GET',\n                'header' => [\n                    'User-Agent: Mozilla/5.0 (compatible; CCCRJ-Scraper/1.0; +http://www.cccrj.com.br/)',\n                    'Accept: text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8'\n                ],\n                'timeout' => 30\n            ]\n        ]);\n\n        $content = @file_get_contents($url, false, $context);\n        return $content;\n    }\n\n    private function findImagesInPage($html) {\n        $images = [];\n        $dom = new DOMDocument();\n        \n        // Suprimir erros de HTML inválido\n        libxml_use_internal_errors(true);\n        $dom->loadHTML($html);\n        libxml_clear_errors();\n        \n        $xpath = new DOMXPath($dom);\n        $imgElements = $xpath->query('//img[@src]');\n        \n        foreach ($imgElements as $img) {\n            $src = $img->getAttribute('src');\n            if ($src) {\n                $fullUrl = $this->resolveUrl($src, $this->baseUrl);\n                if ($this->isValidImageUrl($fullUrl)) {\n                    $images[] = $fullUrl;\n                }\n            }\n        }\n        \n        return array_unique($images);\n    }\n\n    private function isValidImageUrl($url) {\n        // Verificar se é uma URL válida e tem extensão de imagem\n        $validExtensions = ['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.svg', '.webp'];\n        $extension = strtolower(pathinfo(parse_url($url, PHP_URL_PATH), PATHINFO_EXTENSION));\n        return in_array($extension, $validExtensions) && strpos($url, $this->baseUrl) === 0;\n    }\n\n    private function resolveUrl($url, $baseUrl) {\n        // Resolver URLs relativas\n        if (preg_match('/^https?:\\/\\//', $url)) {\n            // URL absoluta\n            return $url;\n        } elseif (preg_match('/^\\//', $url)) {\n            // Caminho absoluto\n            $parsed = parse_url($baseUrl);\n            return $parsed['scheme'] . '://' . $parsed['host'] . $url;\n        } else {\n            // Caminho relativo\n            $path = dirname(parse_url($baseUrl, PHP_URL_PATH)) . '/' . $url;\n            $path = $this->normalizePath($path);\n            $parsed = parse_url($baseUrl);\n            return $parsed['scheme'] . '://' . $parsed['host'] . $path;\n        }\n    }\n\n    private function normalizePath($path) {\n        $path = str_replace('\\\\', '/', $path);\n        $parts = explode('/', $path);\n        $normalized = [];\n        \n        foreach ($parts as $part) {\n            if ($part === '' || $part === '.') {\n                continue;\n            } elseif ($part === '..') {\n                array_pop($normalized);\n            } else {\n                $normalized[] = $part;\n            }\n        }\n        \n        return '/' . implode('/', $normalized);\n    }\n\n    private function downloadImage($url) {\n        if (in_array($url, $this->downloadedImages)) {\n            return;\n        }\n\n        echo \"Baixando imagem: $url\\n\";\n\n        $context = stream_context_create([\n            'http' => [\n                'method' => 'GET',\n                'header' => [\n                    'User-Agent: Mozilla/5.0 (compatible; CCCRJ-Scraper/1.0; +http://www.cccrj.com.br/)',\n                    'Accept: image/*'\n                ],\n                'timeout' => 30\n            ]\n        ]);\n\n        $imageContent = @file_get_contents($url, false, $context);\n        if ($imageContent === false) {\n            echo \"Erro ao baixar imagem: $url\\n\";\n            return;\n        }\n\n        // Criar nome de arquivo baseado no nome original\n        $filename = basename(parse_url($url, PHP_URL_PATH));\n        if (!$filename || !strpos($filename, '.')) {\n            $extension = pathinfo(parse_url($url, PHP_URL_PATH), PATHINFO_EXTENSION);\n            $filename = 'image_' . md5($url) . (!empty($extension) ? '.' . $extension : '.jpg');\n        }\n        \n        $filepath = $this->outputDir . '/' . $filename;\n        \n        file_put_contents($filepath, $imageContent);\n        echo \"Imagem salva: $filepath\\n\";\n        \n        $this->downloadedImages[] = $url;\n        \n        // Respeitar delay entre requisições\n        sleep($this->delay);\n    }\n\n    public function findAndDownloadImages() {\n        // Páginas para analisar em busca de imagens\n        $pagesToScan = [\n            \"\",\n            \"index.htm\",\n            \"mapa.htm\",\n            \"fale.htm\",\n            \"cccrj/inicio.htm\",\n            \"crmc/inicio.htm\",\n            \"revista/inicio.htm\",\n            \"terminal/inicio.htm\",\n            \"rio/inicio.htm\",\n            \"links/inicio.htm\"\n        ];\n        \n        foreach ($pagesToScan as $page) {\n            $pageUrl = $this->baseUrl . $page;\n            \n            if (in_array($pageUrl, $this->visitedPages)) {\n                continue;\n            }\n            \n            echo \"Analisando $pageUrl por imagens...\\n\";\n            \n            $content = $this->getPageContent($pageUrl);\n            if ($content === false) {\n                echo \"Erro ao obter página: $pageUrl\\n\";\n                continue;\n            }\n            \n            $images = $this->findImagesInPage($content);\n            foreach ($images as $imageUrl) {\n                $this->downloadImage($imageUrl);\n            }\n            \n            $this->visitedPages[] = $pageUrl;\n            \n            // Respeitar delay entre requisições\n            sleep($this->delay);\n        }\n        \n        echo \"Processo de download de imagens concluído. \" . count($this->downloadedImages) . \" imagens baixadas.\\n\";\n    }\n}\n\n// Executar o finder de imagens\n$imageFinder = new ImageFinder();\n$imageFinder->findAndDownloadImages();\n\n?>